function ownerState() {
  if (running) return "pilot";
  // TEXT_ENTRY, not TYPING: a focused button still drives, so saying the keys are paused
  // would be a lie the moment anyone clicked Reset.
  if (document.activeElement?.matches?.(TEXT_ENTRY)) return "typing";
  for (const code of held) if (MOTION.has(code)) return "hand";
  return "live";
}

function say(event) {
  switch (event.kind) {
    case "start":
      ui.transcript.replaceChildren();
      line("goal", `<b>goal</b> ${escape(event.goal)}
        <span class="fine">contract: ${event.contract.allow.length} verbs allowed, ${event.contract.maxSteps} steps</span>`);
      break;
    case "call":
      line("call", `<b>${escape(event.name)}</b>(${escape(JSON.stringify(event.args ?? {}))})`);
      break;
    case "result":
      line(event.ok ? "result" : "result bad", escape(event.summary));
      break;
    case "end":
      line(`end ${event.outcome}`, `<b>${escape(event.outcome)}</b> ${escape(event.reason)}`);
      break;
    case "reset":
      line("note", "the duck is back where it started");
      break;
    // The hand's discrete acts only. W/A/S/D and Q/E write nothing on purpose: one line per
    // keypress would bury the model's reasoning. A verb leaves a line; a twist leaves a
    // number, and the readout is where driving is recorded.
    case "handover":
      line("handover", `<b>you took the controls</b> <kbd>${escape(event.key)}</kbd>`);
      break;
    case "hand":
      line("hand", `<b>hand</b> ${escape(event.text)}`);
      break;
    case "refused":
      line("refused",
        `<b>no brain attached</b> This robot understands a twist — three numbers, ` +
        `<code>vx, vy, wz</code> — and a walking policy that turns them into steps. It has ` +
        `never seen the words <em>${escape(event.goal)}</em>, and nothing in it can turn them ` +
        `into one. Your keys still work; they always did. What is missing is the layer that ` +
        `reads the sentence.`);
      break;
    default:
      break;
  }
}

function manualTwist() {
  // Shift is a modifier, not a motor key: it never barges in and never takes the lease, it
  // only changes what A and D mean. It is tracked in `held` so its own keydown and keyup
  // re-run this mid-hold.
  const strafe = held.has("ShiftLeft") || held.has("ShiftRight");
  let vx = 0, vy = 0, wz = 0;
  if (held.has("KeyW")) vx += SPEED.vx;
  if (held.has("KeyS")) vx -= SPEED.vx;
  if (held.has("KeyA")) strafe ? (vy += SPEED.vy) : (wz += SPEED.wz);
  if (held.has("KeyD")) strafe ? (vy -= SPEED.vy) : (wz -= SPEED.wz);
  return [vx, vy, wz];
}

async function handStandUp() {
  if (duck.posture !== "fallen") { say({ kind: "hand", text: "stand up — already standing" }); return; }
  const signal = handSignal();
  duck.standUp();
  await runtime.sleep(1.0, signal);
  say({ kind: "hand", text: duck.posture === "standing" ? "stand up — upright" : "stand up — still down" });
}

function dispatchOneShot(code) {
  if (ONCE.has(code)) flashKey(code);
  switch (code) {
    case "Space": handStop(); break;
    case "KeyK": handKick().catch(handFailed("kick")); break;
    case "KeyR": handStandUp().catch(handFailed("stand up")); break;
    case "KeyG": duck.setHead(0); break;
    case "KeyO": say({ kind: "hand", text: JSON.stringify(duck.observe()) }); break;
    case "Digit1": pickCamera("follow"); break;
    case "Digit2": pickCamera("duck"); break;
    default: break;
  }
}

kick(leg = "right") {
    this.kicks += 1;
    if (this.posture !== "standing") return false;
    const { distance, bearing } = this.relative(this.ballX, this.ballY);
    this.kickOrigin = [this.ballX, this.ballY];
    if (distance > KICK_RANGE || Math.abs((bearing * 180) / Math.PI) > KICK_CONE_DEG) return false;
    this.kicksConnected += 1;
    // Gaussian with sigma six degrees, as sim2d and sim3d both use. A uniform +/- 5.7 was a
    // different distribution wearing the same numbers, so a kick here missed differently.
    const skew = this.gaussian(0, (6 * Math.PI) / 180) + (leg === "left" ? 0.05 : -0.05);
    const angle = this.pose.theta + skew;
    this.data.qvel[this.ballV] = KICK_SPEED * Math.cos(angle);
    this.data.qvel[this.ballV + 1] = KICK_SPEED * Math.sin(angle);
    this.data.qvel[this.ballV + 2] = 0;  // Python zeroes it: a kicked ball rolls, it does not hop
    return true;
  }

updatePosture() {
    if (this.posture === "sitting") return;
    const down = this.gravityZ > FALL_TILT || this.data.qpos[this.freeQ + 2] < FALL_HEIGHT;
    this.downTicks = down ? this.downTicks + 1 : 0;
    if (this.downTicks >= FALL_DEBOUNCE) this.posture = "fallen";
    else if (!down && this.posture === "fallen") this.posture = "standing";
  }

sleep(seconds, signal = null) {
    if (this.error) return Promise.reject(this.error);
    if (signal?.aborted) return Promise.reject(signal.reason);
    if (seconds <= 0) return Promise.resolve();
    return new Promise((resolve, reject) => {
      // The listener has to come OFF again when the sleep ends normally. `once: true` only
      // covers the abort path, and `move` issues up to a hundred slices per verb against a
      // budget of eighteen steps, so one run left ~1800 live closures on a single signal —
      // and an abort then walked every one of them.
      const done = () => signal?.removeEventListener("abort", onAbort);
      const waiter = {
        left: seconds,
        resolve: () => { done(); resolve(); },
        reject: (error) => { done(); reject(error); },
      };
      // Stop has to reach a move that is already running. Without this a ten second move ran
      // to completion after the button, and the duck kept walking the whole time.
      const onAbort = () => {
        this._waiters = this._waiters.filter((w) => w !== waiter);
        reject(signal.reason);
      };
      this._waiters.push(waiter);
      signal?.addEventListener("abort", onAbort, { once: true });
    });
  }

_wake(dt) {
    if (!this._waiters.length) return;
    const still = [];
    for (const waiter of this._waiters) {
      waiter.left -= dt;
      if (waiter.left <= 0) waiter.resolve();
      else still.push(waiter);
    }
    this._waiters = still;
  }

export function checkParams(schema, args) {
  if (args === null || typeof args !== "object" || Array.isArray(args)) {
    return `expected an object of arguments, got ${JSON.stringify(args)}`;
  }
  const properties = schema.properties ?? {};
  if (schema.additionalProperties === false) {
    const unknown = Object.keys(args).filter((k) => !(k in properties));
    if (unknown.length) return `unknown parameter(s): ${unknown.join(", ")}`;
  }
  for (const name of schema.required ?? []) {
    if (!(name in args)) return `${name} is required`;
  }
  for (const [name, value] of Object.entries(args)) {
    const rule = properties[name];
    if (!rule) continue;
    if (rule.type === "number") {
      if (typeof value !== "number" || !Number.isFinite(value)) {
        return `${name} must be a finite number, got ${JSON.stringify(value)}`;
      }
      if (rule.minimum !== undefined && value < rule.minimum) {
        return `${name} must be at least ${rule.minimum}, got ${value}`;
      }
      if (rule.maximum !== undefined && value > rule.maximum) {
        return `${name} must be at most ${rule.maximum}, got ${value}`;
      }
    }
    if (rule.type === "string") {
      if (typeof value !== "string") return `${name} must be a string`;
      if (rule.maxLength !== undefined && value.length > rule.maxLength) {
        return `${name} must be at most ${rule.maxLength} characters`;
      }
      if (rule.enum && !rule.enum.includes(value)) {
        return `${name} must be one of ${rule.enum.join(", ")}`;
      }
    }
  }
  return null;
}

export async function pilot({ runtime, goal, provider, contract = DEFAULT_CONTRACT, onEvent, signal }) {
  const duck = runtime.duck;
  const history = [];
  const startedAt = duck.t;
  let last = null;
  onEvent({ kind: "start", goal, contract });

  for (let step = 0; step < contract.maxSteps; step++) {
    if (signal?.aborted) { onEvent({ kind: "end", outcome: "aborted", reason: abortedBecause(signal) }); return; }
    if (duck.t - startedAt > contract.maxMinutes * 60) {
      onEvent({ kind: "end", outcome: "budget", reason: "the time budget is spent" });
      return;
    }
    const observation = observationText(duck, step, contract, last);
    onEvent({ kind: "observation", text: observation, step });
    let call;
    try {
      call = await provider.step({
        system: systemPrompt(goal, contract),
        history,
        observation,
        tools: toolSchemas(contract),
        signal,
      });
    } catch (error) {
      // An abort during the model's turn is not a provider failure. Without the signal on the
      // fetch this arrived seconds late, after a response nobody wanted and the visitor's own
      // key had already been billed for.
      if (signal?.aborted) { onEvent({ kind: "end", outcome: "aborted", reason: abortedBecause(signal) }); return; }
      onEvent({ kind: "end", outcome: "error", reason: String(error.message || error) });
      return;
    }
    history.push({ observation, call });
    onEvent({ kind: "call", name: call.name, args: call.arguments });

    if (call.name === "declare_success" || call.name === "declare_failure") {
      onEvent({
        kind: "end",
        outcome: call.name === "declare_success" ? "success" : "failure",
        reason: call.arguments?.reason ?? "",
      });
      return;
    }
    const verb = VERBS[call.name];
    if (!verb || !contract.allow.includes(call.name)) {
      // Refused, and the run continues: the model is told and may choose differently. This
      // is the executor's job, and the reason a contract is worth having.
      last = { name: call.name, ok: false, summary: `refused: ${call.name} is not in this task's allowlist` };
      onEvent({ kind: "result", ...last });
      continue;
    }
    const complaint = checkParams(verb.params, call.arguments ?? {});
    if (complaint !== null) {
      // Refused before anything moves, exactly as a pydantic ValidationError does in Python.
      last = { name: call.name, ok: false, summary: `refused: ${complaint}` };
      onEvent({ kind: "result", ...last });
      continue;
    }
    try {
      // The signal is passed down. It was not, so `Runtime.sleep`'s abort listener was dead
      // code and a ten second `move` ran to completion after Stop, exactly as the comment
      // above that listener claimed it would not.
      const outcome = await verb.run(runtime, call.arguments ?? {}, signal);
      // A verb may report that it did not work. `ok: true` used to be unconditional, so a
      // kick that missed read as a success and the failure style was unreachable.
      last =
        typeof outcome === "string"
          ? { name: call.name, ok: true, summary: outcome }
          : { name: call.name, ok: outcome.ok, summary: outcome.summary, data: outcome.data };
    } catch (error) {
      runtime.duck.setTwist(0, 0, 0); // a verb that threw leaves the robot stopped
      // An abort is not a failed verb: this used to print `result move FAILED AbortError`.
      if (signal?.aborted) { onEvent({ kind: "end", outcome: "aborted", reason: abortedBecause(signal) }); return; }
      last = { name: call.name, ok: false, summary: String(error.message || error) };
    }
    onEvent({ kind: "result", ...last });
  }
  runtime.duck.setTwist(0, 0, 0);
  onEvent({ kind: "end", outcome: "budget", reason: `the ${contract.maxSteps} step budget is spent` });
}

export function startingApi(provider, model) {
  const known = CATALOGUE[provider]?.entries.find((entry) => entry.id === model);
  return known?.api === "responses" ? "responses" : "chat";
}

export function makeProvider({ provider, key, model, baseUrl, api }) {
  const spec = PROVIDERS[provider];
  if (!spec) throw new ProviderError(`unknown provider ${provider}`);
  if (spec.needsKey && !key) throw new ProviderError(`${spec.label} needs your API key`);
  // The default comes from the catalogue for a cloud vendor and from the spec for Local. The
  // id itself is NOT checked against the catalogue: a model quackd has not heard of has to
  // reach the vendor and come back in the vendor's own words, which is the only answer that
  // can be right about a list this page does not own.
  const chosen = model || CATALOGUE[provider]?.default || spec.defaultModel;
  // Where the caller said nothing, the catalogue decides, so a caller who reaches for
  // `makeProvider` directly gets the same answer the page does. `quackd/agent/providers/
  // openai.py` resolves it in the same order for the same reason.
  const startsOn = api || startingApi(provider, chosen);
  if (provider === "anthropic") return anthropic({ key, model: chosen });
  if (provider === "gemini") return gemini({ key, model: chosen });
  // Every other cloud vendor is OpenAI-shaped, so it is one client with a different base URL,
  // a different label on its errors and whatever `tool_choice` that vendor accepts. Local is
  // the same client again, with the only base URL on the page a visitor may type.
  if (spec.needsKey) {
    return openaiCompatible({
      key,
      model: chosen,
      baseUrl: spec.baseUrl,
      label: spec.label,
      toolChoice: spec.toolChoice,
      api: startsOn,
    });
  }
  return openaiCompatible({
    key: key || "",
    model: chosen,
    baseUrl: localBaseUrl(baseUrl || spec.baseUrl),
    label: "your local server",
    toolChoice: spec.toolChoice,
  });
}

export function localBaseUrl(raw) {
  let url;
  try {
    url = new URL(raw);
  } catch {
    throw new ProviderError(`"${raw}" is not a URL. Try http://localhost:11434/v1`);
  }
  const loopback = ["localhost", "127.0.0.1", "[::1]", "::1"].includes(url.hostname);
  if (url.protocol === "https:" || (url.protocol === "http:" && loopback)) {
    return raw;
  }
  throw new ProviderError(
    `refusing to send a key to ${url.host} over ${url.protocol.replace(":", "")}. ` +
      "Use https, or http only for a server on this machine."
  );
}

geometryFor(type, size, dataid) {
    switch (type) {
      case PLANE: {
        const half = size[0] > 0 ? size[0] : 6;
        const plane = new THREE.PlaneGeometry(half * 2, (size[1] > 0 ? size[1] : half) * 2, 1, 1);
        return plane; // already in the xy plane, which is MuJoCo's floor
      }
      case SPHERE: return new THREE.SphereGeometry(size[0], 24, 16);
      case ELLIPSOID: {
        const sphere = new THREE.SphereGeometry(1, 24, 16);
        sphere.scale(size[0], size[1], size[2]);
        return sphere;
      }
      // Known wrong, and harmless only while nothing in the arena is a capsule: this builds
      // three.js's capsule without the rotateX the CYLINDER branch below applies, and three.js
      // runs both along y where MuJoCo runs them along z. A capsule geom would be drawn lying
      // on the floor. Rotate it the same way when one first appears.
      case CAPSULE: return new THREE.CapsuleGeometry(size[0], size[1] * 2, 6, 12);
      case CYLINDER: {
        const cylinder = new THREE.CylinderGeometry(size[0], size[0], size[1] * 2, 20);
        cylinder.rotateX(Math.PI / 2); // three.js cylinders run along y; MuJoCo's along z
        return cylinder;
      }
      case BOX: return new THREE.BoxGeometry(size[0] * 2, size[1] * 2, size[2] * 2);
      case MESH: return this.meshGeometry(dataid);
      default: return null;
    }
  }

meshGeometry(id) {
    const { model } = this.duck;
    if (id < 0) return null;
    const vertexAt = model.mesh_vertadr[id] * 3;
    const vertexCount = model.mesh_vertnum[id];
    const faceAt = model.mesh_faceadr[id] * 3;
    const faceCount = model.mesh_facenum[id];
    const vertices = new Float32Array(vertexCount * 3);
    for (let i = 0; i < vertexCount * 3; i++) vertices[i] = model.mesh_vert[vertexAt + i];
    const indices = new Uint32Array(faceCount * 3);
    for (let i = 0; i < faceCount * 3; i++) indices[i] = model.mesh_face[faceAt + i];
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", new THREE.BufferAttribute(vertices, 3));
    geometry.setIndex(new THREE.BufferAttribute(indices, 1));
    geometry.computeVertexNormals();
    return geometry;
  }
